INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('942e904c-ce19-5558-a57f-b529b43e5670', 'Australia Workplace Gender Equality Act', 'Workplace Gender Equality Act. No. 91, 1986', 'This act replaces the Equal Opportunity for Women in the Workplace Act 1999. The new, strengthened legislation aims to improve and promote equality for both women and men in the workplace.', 'This act replaces the Equal Opportunity for Women in the Workplace Act 1999. The new, strengthened legislation aims to improve and promote equality for both women and men in the workplace.', 'This act replaces the Equal Opportunity for Women in the Workplace Act 1999. The new, strengthened legislation aims to improve and promote equality for both women and men in the workplace.', 'Australia', 'climate', 'in_force', '2016-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_13', ARRAY['australia', 'regulations', 'mandatory', 'sdg5', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('07c9f8fa-6e8f-5cf3-8072-c25ee3c52418', 'Australia ASX Listing Rules', 'ASX Listing Rules', 'The ASX Listing Rules (2016) establish a regulatory framework governing entities listed on the Australian Securities Exchange (ASX). These rules ensure transparency, integrity, and investor protection by setting standards for disclosure, governance, and ongoing compliance. Key provisions include continuous disclosure requirements, governance reporting obligations, and protocols for capital raising and related-party transactions.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('94915591-3846-5d27-9ba5-85feda530f1f', 'Australia Renewable Energy (Electricity) Act 2000', 'Renewable Energy (Electricity) Act 2000 No. 174, 2000', 'An act for the establishment and administration of a scheme to encourage additional electricity generation from renewable energy sources, and for related purposes.', 'An act for the establishment and administration of a scheme to encourage additional electricity generation from renewable energy sources, and for related purposes.', 'An act for the establishment and administration of a scheme to encourage additional electricity generation from renewable energy sources, and for related purposes.', 'Australia', 'climate', 'in_force', '2015-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_10', ARRAY['australia', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0c2ea016-04b9-5929-aea9-79863ba401b3', 'ESG Reporting Guide for Australian Companies', 'ESG Reporting Guide for Australian Companies, 2015', 'This updated Guide highlights the types of information needed by our member organisations to understand, price, analyse and manage ESG investment risks.', 'This updated Guide highlights the types of information needed by our member organisations to understand, price, analyse and manage ESG investment risks.', 'This updated Guide highlights the types of information needed by our member organisations to understand, price, analyse and manage ESG investment risks.', 'Australia', 'climate', 'in_force', '2015-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_17', ARRAY['australia', 'sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7ea758af-88b5-5af1-aaec-b7d170deb4d5', 'Enduring Value. The Australian minerals industry framework', 'Enduring Value. The Australian minerals industry framework for sustainable development', 'Enduring Value puts the minerals industry’s commitment to sustainable development into practice.   In the mining and metals sector, sustainable development means that minerals projects should be safe, financially profitable, technically appropriate, and environmentally and socially responsible.', 'Enduring Value puts the minerals industry’s commitment to sustainable development into practice.   In the mining and metals sector, sustainable development means that minerals projects should be safe, financially profitable, technically appropriate, and environmentally and socially responsible.', 'Enduring Value puts the minerals industry’s commitment to sustainable development into practice.   In the mining and metals sector, sustainable development means that minerals projects should be safe, financially profitable, technically appropriate, and environmentally and socially responsible.', 'Australia', 'climate', 'in_force', '2015-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_43', ARRAY['australia', 'voluntary_frameworks', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b387e4b1-767e-5fde-89da-7ce441945661', 'Australia National Pollutant Inventory Guide. Version 6.1', 'National Pollutant Inventory Guide. Version 6.1', 'The NPI is an Australian database of emissions from various industrial facility sources, and diffuse sources. The NPI Guide helps facility managers, or operators, estimate emissions for the NPI. It helps a facility find out whether it needs to report its emissions of NPI substances.', 'The NPI is an Australian database of emissions from various industrial facility sources, and diffuse sources. The NPI Guide helps facility managers, or operators, estimate emissions for the NPI. It helps a facility find out whether it needs to report its emissions of NPI substances.', 'The NPI is an Australian database of emissions from various industrial facility sources, and diffuse sources. The NPI Guide helps facility managers, or operators, estimate emissions for the NPI. It helps a facility find out whether it needs to report its emissions of NPI substances.', 'Australia', 'climate', 'in_force', '2015-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_62', ARRAY['australia', 'sdg13', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb4871c8-2aff-54cb-b194-cc2b3c6c0acd', 'Australia Corporate Governance Principles and Recommendations', 'Corporate Governance Principles and Recommendations. 3rd Edition, 2014', 'These Principles and Recommendations set out recommended corporate governance practices for entities listed on the ASX that, in the Council’s view, are likely to achieve good governance outcomes and meet the reasonable expectations of most investors in most situations.', 'These Principles and Recommendations set out recommended corporate governance practices for entities listed on the ASX that, in the Council’s view, are likely to achieve good governance outcomes and meet the reasonable expectations of most investors in most situations.', 'These Principles and Recommendations set out recommended corporate governance practices for entities listed on the ASX that, in the Council’s view, are likely to achieve good governance outcomes and meet the reasonable expectations of most investors in most situations.', 'Australia', 'governance', 'in_force', '2014-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_11', ARRAY['australia', 'guidance_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('56510f05-4e65-5329-900e-29cc128b94bc', 'Australian Water Accounting Standard 2', 'Australian Water Accounting Standard 2, 2014', 'This standard establishes the requirements for assurance engagements. It provides application and other explanatory material regarding the assurance practitioner''s responsibilities when accepting, conducting and reporting on a general purpose water accounting report.', 'This standard establishes the requirements for assurance engagements. It provides application and other explanatory material regarding the assurance practitioner''s responsibilities when accepting, conducting and reporting on a general purpose water accounting report.', 'This standard establishes the requirements for assurance engagements. It provides application and other explanatory material regarding the assurance practitioner''s responsibilities when accepting, conducting and reporting on a general purpose water accounting report.', 'Australia', 'climate', 'in_force', '2014-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_2', ARRAY['australia', 'voluntary_frameworks', 'sdg6', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb87e5c3-c7d1-5565-87a6-ccf65766a1f0', 'Australia Assurance Engagements. ASAE 3410. Assurance Engagements on Greenhouse', 'Standard on Assurance Engagements. ASAE 3410. Assurance Engagements on Greenhouse Gas Statements', 'This Standard on Assurance Engagements establishes requirements and provides application and other explanatory material regarding the assurance practitioner’s responsibilities when accepting, conducting, and reporting on an engagement to provide reasonable or limited assurance on a greenhouse gas statement.', 'This Standard on Assurance Engagements establishes requirements and provides application and other explanatory material regarding the assurance practitioner’s responsibilities when accepting, conducting, and reporting on an engagement to provide reasonable or limited assurance on a greenhouse gas statement.', 'This Standard on Assurance Engagements establishes requirements and provides application and other explanatory material regarding the assurance practitioner’s responsibilities when accepting, conducting, and reporting on an engagement to provide reasonable or limited assurance on a greenhouse gas statement.', 'Australia', 'climate', 'in_force', '2014-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_41', ARRAY['australia', 'sdg13', 'voluntary_frameworks', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a46c6fd-5754-5d00-981f-270beadd6c7c', 'Australia Prudential Practice Guide SPG 530 Investment Governance', 'Prudential Practice Guide SPG 530 Investment Governance', 'This Prudential Standard establishes requirements for an RSE licensee to implement a sound investment governance framework and to manage investments in a manner consistent with the interests of beneficiaries.', 'This Prudential Standard establishes requirements for an RSE licensee to implement a sound investment governance framework and to manage investments in a manner consistent with the interests of beneficiaries.', 'This Prudential Standard establishes requirements for an RSE licensee to implement a sound investment governance framework and to manage investments in a manner consistent with the interests of beneficiaries.', 'Australia', 'governance', 'in_force', '2013-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_20', ARRAY['australia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('20bdad8e-3f66-51a9-9b06-caed39894641', 'Australia FSC Standard Superannuation Governance Policy', 'FSC Standard No. 20 Superannuation Governance Policy', 'In 2013, the Financial Services Council (FSC) in Australia released the "FSC Standard No. 20 Superannuation Governance Policy," which outlines a set of principles and practices that aim to improve the governance and accountability of superannuation funds in the country. The standard covers a range of topics, including the roles and responsibilities of trustees, the composition and independence of boards, the management of conflicts of interest, risk management practices, and the disclosure of information to members. It also establishes guidelines for the selection and monitoring of service providers, including investment managers and custodians. The standard is mandatory for FSC member companies that provide superannuation products and services, and it is designed to be compatible with the requirements of Australian law and regulatory frameworks. The FSC conducts regular reviews of the standard to ensure that it remains relevant and effective in promoting good governance practices in the superannuation industry.', 'In 2013, the Financial Services Council (FSC) in Australia released the "FSC Standard No. 20 Superannuation Governance Policy," which outlines a set of principles and practices that aim to improve the governance and accountability of superannuation funds in the country. The standard covers a range of topics, including the roles and responsibilities of trustees, the composition and independence of boards, the management of conflicts of interest, risk management practices, and the disclosure of information to members. It also establishes guidelines for the selection and monitoring of service providers, including investment managers and custodians. The standard is mandatory for FSC member companies that provide superannuation products and services, and it is designed to be compatible with the requirements of Australian law and regulatory frameworks. The FSC conducts regular reviews of the standard to ensure that it remains relevant and effective in promoting good governance practices in the superannuation industry.', 'In 2013, the Financial Services Council (FSC) in Australia released the "FSC Standard No. 20 Superannuation Governance Policy," which outlines a set of principles and practices that aim to improve the governance and accountability of superannuation funds in the country. The standard covers a range of topics, including the roles and responsibilities of trustees, the composition and independence of boards, the management of conflicts of interest, risk management practices, and the disclosure of information to members. It also establishes guidelines for the selection and monitoring of service providers, including investment managers and custodians. The standard is mandatory for FSC member companies that provide superannuation products and services, and it is designed to be compatible with the requirements of Australian law and regulatory frameworks. The FSC conducts regular reviews of the standard to ensure that it remains relevant and effective in promoting good governance practices in the superannuation industry.', 'Australia', 'governance', 'in_force', '2013-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_22', ARRAY['australia', 'voluntary', 'sdg16', 'disclosure', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
