INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa564393-7752-5dec-ac11-15c03e6989c0', 'Australia Regulatory Guide 247. Effective Disclosure in an Operating', 'Regulatory Guide 247. Effective Disclosure in an Operating and Financial review', 'This guide is for listed entities and their directors. It sets out our guidance for directors on providing useful and meaningful information to shareholders or unit holders when preparing an operating and financial review (OFR) in a directors’ report.', 'This guide is for listed entities and their directors. It sets out our guidance for directors on providing useful and meaningful information to shareholders or unit holders when preparing an operating and financial review (OFR) in a directors’ report.', 'This guide is for listed entities and their directors. It sets out our guidance for directors on providing useful and meaningful information to shareholders or unit holders when preparing an operating and financial review (OFR) in a directors’ report.', 'Australia', 'climate', 'in_force', '2013-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_4', ARRAY['australia', 'mandatory', 'guidance_frameworks', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('adb6ad64-b7d3-565b-aa55-c271f1a7e4c6', 'Australia Reference Guide 2019. Guide to reporting under the', 'Reference Guide 2019. Guide to reporting under the Workplace Gender Equality Act 2012', 'This reference guide is a companion document to the “Indicative format: Workplace profile and reporting questionnaire.” It has detailed information for employers about how to: (1) report under the Workplace Gender Equality Act 2012 (Act), including who needs to do this; (2) comply with the Act’s six gender equality indicators (GEIs); and (3) complete their workplace profile and questionnaire online.', 'This reference guide is a companion document to the “Indicative format: Workplace profile and reporting questionnaire.” It has detailed information for employers about how to: (1) report under the Workplace Gender Equality Act 2012 (Act), including who needs to do this; (2) comply with the Act’s six gender equality indicators (GEIs); and (3) complete their workplace profile and questionnaire online.', 'This reference guide is a companion document to the “Indicative format: Workplace profile and reporting questionnaire.” It has detailed information for employers about how to: (1) report under the Workplace Gender Equality Act 2012 (Act), including who needs to do this; (2) comply with the Act’s six gender equality indicators (GEIs); and (3) complete their workplace profile and questionnaire online.', 'Australia', 'climate', 'in_force', '2012-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_68', ARRAY['australia', 'regulations', 'mandatory', 'sdg5', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ad44a628-a18a-54b5-a91b-4e27412a2d9d', 'Australia Carbon Credits (Carbon Farming Initiative) Act', 'Carbon Credits (Carbon Farming Initiative) Act, 2011', 'This Act aims to implement obligations that Australia has under the Climate Change Convention and the Kyoto Protocol, create incentives for people to carry on certain offsets projects and to increase carbon abatement in a manner that is consistent with the protection of Australia’s environment and that improves resilience to the effects of climate change.', 'This Act aims to implement obligations that Australia has under the Climate Change Convention and the Kyoto Protocol, create incentives for people to carry on certain offsets projects and to increase carbon abatement in a manner that is consistent with the protection of Australia’s environment and that improves resilience to the effects of climate change.', 'This Act aims to implement obligations that Australia has under the Climate Change Convention and the Kyoto Protocol, create incentives for people to carry on certain offsets projects and to increase carbon abatement in a manner that is consistent with the protection of Australia’s environment and that improves resilience to the effects of climate change.', 'Australia', 'climate', 'in_force', '2011-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_1', ARRAY['australia', 'sdg13', 'sdg2', 'regulations', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('33b308ea-12d2-52b1-a431-b7a5726c5069', 'Green marketing and the Australian Consumer Law', 'Green marketing and the Australian Consumer Law', 'A guide to educate businesses about their obligations regarding environmental claims under the Competition and Consumer Act 2010. It aims to assist manufacturers, suppliers, advertisers and others to assess the strength of any environmental claims they make and to improve the accuracy and usefulness to consumers of their: (1) labelling’ (2) packaging and (3) advertising.', 'A guide to educate businesses about their obligations regarding environmental claims under the Competition and Consumer Act 2010. It aims to assist manufacturers, suppliers, advertisers and others to assess the strength of any environmental claims they make and to improve the accuracy and usefulness to consumers of their: (1) labelling’ (2) packaging and (3) advertising.', 'A guide to educate businesses about their obligations regarding environmental claims under the Competition and Consumer Act 2010. It aims to assist manufacturers, suppliers, advertisers and others to assess the strength of any environmental claims they make and to improve the accuracy and usefulness to consumers of their: (1) labelling’ (2) packaging and (3) advertising.', 'Australia', 'climate', 'in_force', '2011-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_70', ARRAY['australia', 'regulations', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('869897e7-356c-57e1-8920-7544160b35bc', 'ESG Reporting Guide for Australian Companies. First Edition', 'ESG Reporting Guide for Australian Companies. First Edition 2011', 'The Guide provides specific guidance on the information that companies should consider and disclose, and secondly, by facilitating greater consistency and comparability of data across different companies and sectors.', 'The Guide provides specific guidance on the information that companies should consider and disclose, and secondly, by facilitating greater consistency and comparability of data across different companies and sectors.', 'The Guide provides specific guidance on the information that companies should consider and disclose, and secondly, by facilitating greater consistency and comparability of data across different companies and sectors.', 'Australia', 'climate', 'in_force', '2011-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_72', ARRAY['australia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5a0abebd-346b-5e11-9846-95d9a04c4ecf', 'Australia Corporate Governance Principles and Recommendations', 'Corporate Governance Principles and Recommendations. 2nd Edition, 2010', 'This document marks the first revision of the Council’s corporate governance Principles and Recommendations since they were issued in March 2003. Corporate governance is a dynamic force that keeps evolving.  The Australian Stock Exchange (ASX) Corporate Governance Council’s challenge is to ensure that the Principles and Recommendations remain relevant to the Australian business and investment communities. The revised Principles and Recommendations are part of that process. They reflect the contributions of more than 100 public submissions and will take effect from 1 January 2008.', 'This document marks the first revision of the Council’s corporate governance Principles and Recommendations since they were issued in March 2003. Corporate governance is a dynamic force that keeps evolving.  The Australian Stock Exchange (ASX) Corporate Governance Council’s challenge is to ensure that the Principles and Recommendations remain relevant to the Australian business and investment communities. The revised Principles and Recommendations are part of that process. They reflect the contributions of more than 100 public submissions and will take effect from 1 January 2008.', 'This document marks the first revision of the Council’s corporate governance Principles and Recommendations since they were issued in March 2003. Corporate governance is a dynamic force that keeps evolving.  The Australian Stock Exchange (ASX) Corporate Governance Council’s challenge is to ensure that the Principles and Recommendations remain relevant to the Australian business and investment communities. The revised Principles and Recommendations are part of that process. They reflect the contributions of more than 100 public submissions and will take effect from 1 January 2008.', 'Australia', 'governance', 'in_force', '2010-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_27', ARRAY['australia', 'guidance_frameworks', 'sdg16', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7e9839c9-a351-5394-b035-343c31f93ae1', 'Australian Water Accounting Standard 1', 'Australian Water Accounting Standard 1, 2010', 'This standard prescribes the basis for preparing and presenting a General Purpose Water Accounting Report (GPWAR). It sets out requirements for the recognition, quantification, presentation and disclosure of items in a GPWAR. The standard also includes three appendices: a list of defined terms; illustrative guidance; and a basis for conclusions outlining the discussion and assumptions that informed its development.', 'This standard prescribes the basis for preparing and presenting a General Purpose Water Accounting Report (GPWAR). It sets out requirements for the recognition, quantification, presentation and disclosure of items in a GPWAR. The standard also includes three appendices: a list of defined terms; illustrative guidance; and a basis for conclusions outlining the discussion and assumptions that informed its development.', 'This standard prescribes the basis for preparing and presenting a General Purpose Water Accounting Report (GPWAR). It sets out requirements for the recognition, quantification, presentation and disclosure of items in a GPWAR. The standard also includes three appendices: a list of defined terms; illustrative guidance; and a basis for conclusions outlining the discussion and assumptions that informed its development.', 'Australia', 'climate', 'in_force', '2010-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_3', ARRAY['australia', 'voluntary_frameworks', 'sdg6', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03739c87-d399-5f8e-84bb-383d3acbd63b', 'Australia National Greenhouse and Energy Reporting Regulations', 'National Greenhouse and Energy Reporting Regulations, 2008', 'These regulations set out the details that establish compliance rules and procedures for administering the National Greenhouse and Energy Reporting (NGER) Act, 2007.', 'These regulations set out the details that establish compliance rules and procedures for administering the National Greenhouse and Energy Reporting (NGER) Act, 2007.', 'These regulations set out the details that establish compliance rules and procedures for administering the National Greenhouse and Energy Reporting (NGER) Act, 2007.', 'Australia', 'climate', 'in_force', '2008-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_8', ARRAY['australia', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3762647a-8d0c-5c75-abe3-5e032d320185', 'Australia Energy Efficiency Opportunities Amendment Act', 'Energy Efficiency Opportunities Amendment Act, 2007', 'This act aims to improve the identification and evaluation of energy efficiency opportunities by large energy using businesses and, as a result, to encourage implementation of cost-effective energy efficiency opportunities.', 'This act aims to improve the identification and evaluation of energy efficiency opportunities by large energy using businesses and, as a result, to encourage implementation of cost-effective energy efficiency opportunities.', 'This act aims to improve the identification and evaluation of energy efficiency opportunities by large energy using businesses and, as a result, to encourage implementation of cost-effective energy efficiency opportunities.', 'Australia', 'climate', 'in_force', '2007-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_14', ARRAY['australia', 'regulations', 'sdg7', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dcadc428-7f0a-5660-abe2-7678674f58c6', 'Australia National Greenhouse and Energy Reporting Act', 'National Greenhouse and Energy Reporting Act. No. 175', 'The National Greenhouse and Energy Reporting Act 2007 (NGER Act) establishes a national framework for reporting greenhouse gas (GHG) emissions, energy production, and energy consumption by corporations operating in Australia. Enacted to provide consistent, transparent, and reliable data, the Act supports the development of policies and programs to reduce emissions and improve energy efficiency. It applies to corporations exceeding specific thresholds for emissions and energy usage.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dfaef372-ed80-5cc7-a8af-541a9e391a98', 'Australia Chapter 4 Periodic Disclosure', 'Chapter 4 Periodic Disclosure, 2003', 'This chapter sets out the relevant periodic disclosure requirements that an entity will be required to satisfy in relation to each quarter, half year and end of year.', 'This chapter sets out the relevant periodic disclosure requirements that an entity will be required to satisfy in relation to each quarter, half year and end of year.', 'This chapter sets out the relevant periodic disclosure requirements that an entity will be required to satisfy in relation to each quarter, half year and end of year.', 'Australia', 'governance', 'in_force', '2003-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_12', ARRAY['australia', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('289e4fa5-d017-5957-8a2c-4014cf86bf03', 'Australia Principles of Good Corporate Governance and Best Practice', 'Principles of Good Corporate Governance and Best Practice Recommendations, 2003', 'This document is offered as guidance only in the sense that any corporate governance regime must be sufficiently flexible to cope with a constantly changing environment. Just as a healthy and robust business environment evolves with circumstances, so too must any guidelines for corporate governance best practice. The ongoing relevance and effectiveness of these guidelines will be periodically reviewed by the ASX Corporate Governance Council. As with the ASX Listing Rules, where the spirit and intention outweighs the letter of the law, so must these guidelines be applied: maintaining an informed and efficient market and preserving investor confidence remain the constant imperatives.', 'This document is offered as guidance only in the sense that any corporate governance regime must be sufficiently flexible to cope with a constantly changing environment. Just as a healthy and robust business environment evolves with circumstances, so too must any guidelines for corporate governance best practice. The ongoing relevance and effectiveness of these guidelines will be periodically reviewed by the ASX Corporate Governance Council. As with the ASX Listing Rules, where the spirit and intention outweighs the letter of the law, so must these guidelines be applied: maintaining an informed and efficient market and preserving investor confidence remain the constant imperatives.', 'This document is offered as guidance only in the sense that any corporate governance regime must be sufficiently flexible to cope with a constantly changing environment. Just as a healthy and robust business environment evolves with circumstances, so too must any guidelines for corporate governance best practice. The ongoing relevance and effectiveness of these guidelines will be periodically reviewed by the ASX Corporate Governance Council. As with the ASX Listing Rules, where the spirit and intention outweighs the letter of the law, so must these guidelines be applied: maintaining an informed and efficient market and preserving investor confidence remain the constant imperatives.', 'Australia', 'governance', 'in_force', '2003-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_33', ARRAY['australia', 'sdg3', 'regulations', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5c25481e-ecd4-5a03-b0c8-b1684c58a4cd', 'Australia Regulatory Guide 65. Section 1013DA Disclosure Guidelines', 'Regulatory Guide 65. Section 1013DA Disclosure Guidelines', 'This guide is for product issuers. It sets out ASIC’s guidelines on how product issuers can meet their obligations under s1013DA of the Corporations Act 2001 to disclose in Product Disclosure Statements (PDSs) how labour standards or environmental, social or ethical considerations are taken into account in selecting, retaining or realising an investment.', 'This guide is for product issuers. It sets out ASIC’s guidelines on how product issuers can meet their obligations under s1013DA of the Corporations Act 2001 to disclose in Product Disclosure Statements (PDSs) how labour standards or environmental, social or ethical considerations are taken into account in selecting, retaining or realising an investment.', 'This guide is for product issuers. It sets out ASIC’s guidelines on how product issuers can meet their obligations under s1013DA of the Corporations Act 2001 to disclose in Product Disclosure Statements (PDSs) how labour standards or environmental, social or ethical considerations are taken into account in selecting, retaining or realising an investment.', 'Australia', 'social', 'in_force', '2003-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_5', ARRAY['australia', 'guidance_frameworks', 'sdg8', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb229ed2-8c15-54ac-ac34-37781bcd7a32', 'Australia Corporate Governance: A guide for fund managers', 'Corporate Governance: A guide for fund managers and corporations. Blue Book', 'This Guidance Note provides (1) a series of guidelines for IFSA Members in determining their approach to Corporate Governance, voting and other issues proposed by public companies in which they invest; (2) provides a series of guidelines for public companies in relation to a range of Corporate Governance issues including disclosure, board and board committee composition, non-executive directors, board and executive remuneration policy and disclosure.', 'This Guidance Note provides (1) a series of guidelines for IFSA Members in determining their approach to Corporate Governance, voting and other issues proposed by public companies in which they invest; (2) provides a series of guidelines for public companies in relation to a range of Corporate Governance issues including disclosure, board and board committee composition, non-executive directors, board and executive remuneration policy and disclosure.', 'This Guidance Note provides (1) a series of guidelines for IFSA Members in determining their approach to Corporate Governance, voting and other issues proposed by public companies in which they invest; (2) provides a series of guidelines for public companies in relation to a range of Corporate Governance issues including disclosure, board and board committee composition, non-executive directors, board and executive remuneration policy and disclosure.', 'Australia', 'climate', 'in_force', '2002-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_28', ARRAY['australia', 'guidance_frameworks', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2cd564ac-7ead-5a8c-8548-e426dfb2233d', 'Australia Corporations Regulations', 'Corporations Regulations, 2001', 'The Corporations Act 2001 (Cth) is the principal legislation regulating business entities (primarily companies) in Australia. It regulates matters such as the formation and operation of companies (in conjunction with a constitution that may be adopted by a company), duties of officers, takeovers and fundraising.', 'The Corporations Act 2001 (Cth) is the principal legislation regulating business entities (primarily companies) in Australia. It regulates matters such as the formation and operation of companies (in conjunction with a constitution that may be adopted by a company), duties of officers, takeovers and fundraising.', 'The Corporations Act 2001 (Cth) is the principal legislation regulating business entities (primarily companies) in Australia. It regulates matters such as the formation and operation of companies (in conjunction with a constitution that may be adopted by a company), duties of officers, takeovers and fundraising.', 'Australia', 'governance', 'in_force', '2001-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_23', ARRAY['australia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3ccb305-3eb4-5bc9-9664-cbfda877639d', 'Australia Corporations Act', 'Corporations Act, 2001', 'This act requires companies that prepare an Annual Directors’ Report to specify whether the entity’s operations are subject to any significant environmental regulations under state or national law. The report must also provide details of the entity’s performance in relation to these environmental regulations.', 'This act requires companies that prepare an Annual Directors’ Report to specify whether the entity’s operations are subject to any significant environmental regulations under state or national law. The report must also provide details of the entity’s performance in relation to these environmental regulations.', 'This act requires companies that prepare an Annual Directors’ Report to specify whether the entity’s operations are subject to any significant environmental regulations under state or national law. The report must also provide details of the entity’s performance in relation to these environmental regulations.', 'Australia', 'climate', 'in_force', '2001-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_7', ARRAY['australia', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('63adb4df-afbe-5287-9530-948c92893b1a', 'Australia Financial Services Reform Act', 'Financial Services Reform Act, 2001', 'Under the act it presents new ethical disclosure requirements. Issuers of financial products are obliged to disclose the extent to which "labor standards or environmental, social or ethical considerations are taken into account in the selection, retention or realization of an investment".', 'Under the act it presents new ethical disclosure requirements. Issuers of financial products are obliged to disclose the extent to which "labor standards or environmental, social or ethical considerations are taken into account in the selection, retention or realization of an investment".', 'Under the act it presents new ethical disclosure requirements. Issuers of financial products are obliged to disclose the extent to which "labor standards or environmental, social or ethical considerations are taken into account in the selection, retention or realization of an investment".', 'Australia', 'governance', 'in_force', '2001-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_9', ARRAY['australia', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e162a3c9-48c4-55e4-b623-947a5d26072a', 'Framework for Public Environmental Reporting. An Australian Approach', 'A Framework for Public Environmental Reporting. An Australian Approach', 'The objectives of the Australian Framework for Public Environmental Reporting are: (1) to provide flexible and broad guidance at a national level on voluntary public environmental reporting; (2) to facilitate voluntary environmental reporting within private and public sectors to provide simple and effective guidance on how to report and what to report; (3) to facilitate reporting to stakeholders with reliable information relevant to their needs and interests; (4) to facilitate transparency, credibility and more consistency in reporting; (5) to be compatible with other related national and international guidelines such as GRI; (6) to be a continuously evolving document that is periodically reviewed and updated.', 'The objectives of the Australian Framework for Public Environmental Reporting are: (1) to provide flexible and broad guidance at a national level on voluntary public environmental reporting; (2) to facilitate voluntary environmental reporting within private and public sectors to provide simple and effective guidance on how to report and what to report; (3) to facilitate reporting to stakeholders with reliable information relevant to their needs and interests; (4) to facilitate transparency, credibility and more consistency in reporting; (5) to be compatible with other related national and international guidelines such as GRI; (6) to be a continuously evolving document that is periodically reviewed and updated.', 'The objectives of the Australian Framework for Public Environmental Reporting are: (1) to provide flexible and broad guidance at a national level on voluntary public environmental reporting; (2) to facilitate voluntary environmental reporting within private and public sectors to provide simple and effective guidance on how to report and what to report; (3) to facilitate reporting to stakeholders with reliable information relevant to their needs and interests; (4) to facilitate transparency, credibility and more consistency in reporting; (5) to be compatible with other related national and international guidelines such as GRI; (6) to be a continuously evolving document that is periodically reviewed and updated.', 'Australia', 'climate', 'in_force', '2000-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_37', ARRAY['australia', 'sdg7', 'voluntary', 'sdg16', 'disclosure', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42dcba62-f1ca-5b90-afff-0bc8c3c82f72', 'Australia Corporate Governance: A Guide for Investment Managers', 'Corporate Governance: A Guide for Investment Managers and Corporations. IFSA Guidance Note No. 2.00', 'This Guidance Note provides (1) a series of guidelines for IFSA Members in determining their approach to Corporate Governance, voting and other issues proposed by public companies in which they invest; (2) a series of guidelines for public companies in relation to a range of Corporate Governance issues including disclosure, board and board committee composition, non-executive directors, board and executive remuneration policy and disclosure.', 'This Guidance Note provides (1) a series of guidelines for IFSA Members in determining their approach to Corporate Governance, voting and other issues proposed by public companies in which they invest; (2) a series of guidelines for public companies in relation to a range of Corporate Governance issues including disclosure, board and board committee composition, non-executive directors, board and executive remuneration policy and disclosure.', 'This Guidance Note provides (1) a series of guidelines for IFSA Members in determining their approach to Corporate Governance, voting and other issues proposed by public companies in which they invest; (2) a series of guidelines for public companies in relation to a range of Corporate Governance issues including disclosure, board and board committee composition, non-executive directors, board and executive remuneration policy and disclosure.', 'Australia', 'climate', 'in_force', '1999-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_29', ARRAY['australia', 'guidance_frameworks', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('df2572db-6456-524c-bff1-2ed61113de11', 'Australia Environment Protection and Biodiversity Conservation Act', 'Environment Protection and Biodiversity Conservation Act 1999', 'The Environment Protection and Biodiversity Conservation Act 1999 is the Australian Government’s central piece of environmental legislation. It provides a legal framework to protect and manage nationally and internationally important flora, fauna, ecological communities and heritage places — defined in the EPBC Act as matters of national environmental significance.', 'The Environment Protection and Biodiversity Conservation Act 1999 is the Australian Government’s central piece of environmental legislation. It provides a legal framework to protect and manage nationally and internationally important flora, fauna, ecological communities and heritage places — defined in the EPBC Act as matters of national environmental significance.', 'The Environment Protection and Biodiversity Conservation Act 1999 is the Australian Government’s central piece of environmental legislation. It provides a legal framework to protect and manage nationally and internationally important flora, fauna, ecological communities and heritage places — defined in the EPBC Act as matters of national environmental significance.', 'Australia', 'climate', 'in_force', '1999-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_56', ARRAY['australia', 'sdg2', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('de731f0c-17fe-56df-b199-3315ae6ec78d', 'Australia National Environment Protection (National Pollutant Inventory) Measure', 'National Environment Protection (National Pollutant Inventory) Measure, 1998', 'The National Pollutant Inventory (NPI) requires industrial companies to report emissions and inventories for specific substances and fuel to regulatory authorities for inclusion in a public database.', 'The National Pollutant Inventory (NPI) requires industrial companies to report emissions and inventories for specific substances and fuel to regulatory authorities for inclusion in a public database.', 'The National Pollutant Inventory (NPI) requires industrial companies to report emissions and inventories for specific substances and fuel to regulatory authorities for inclusion in a public database.', 'Australia', 'climate', 'in_force', '1998-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_6', ARRAY['australia', 'sdg13', 'sdg2', 'sdg10', 'sdg7', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d0faf07-c471-579f-a630-764214df9d69', 'Australia Performance Audit Report. Corporate Governance - Volume One', 'Performance Audit Report. Corporate Governance - Volume One: in Principle', 'This Report (Volume One: Corporate Governance in Principle), considers relations between the Government and boards, and the extent to which boards add value. Various public sector governance models are examined, including those currently operating within NSW and those from five other jurisdictions.', 'This Report (Volume One: Corporate Governance in Principle), considers relations between the Government and boards, and the extent to which boards add value. Various public sector governance models are examined, including those currently operating within NSW and those from five other jurisdictions.', 'This Report (Volume One: Corporate Governance in Principle), considers relations between the Government and boards, and the extent to which boards add value. Various public sector governance models are examined, including those currently operating within NSW and those from five other jurisdictions.', 'Australia', 'climate', 'in_force', '1997-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_25', ARRAY['australia', 'guidance_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('63375904-52c9-56d2-935a-bcf157cf4813', 'Australia Performance Audit Report. Corporate Governance - Volume Two', 'Performance Audit Report. Corporate Governance - Volume Two: In Practice', 'This report (Volume Two: Corporate Governance in Practice) details how actual corporate governance practices by NSW public sector boards compare with “better practice”.', 'This report (Volume Two: Corporate Governance in Practice) details how actual corporate governance practices by NSW public sector boards compare with “better practice”.', 'This report (Volume Two: Corporate Governance in Practice) details how actual corporate governance practices by NSW public sector boards compare with “better practice”.', 'Australia', 'climate', 'in_force', '1997-01-01'::date, 'Australia', 'https://www.carrotsandsticks.org/policies/8_26', ARRAY['sdg4', 'australia', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9bf7a54d-1052-57c9-b568-e80368d73a1b', 'Austria FMA Guide for Managing Sustainability Risks', 'FMA Guide for Managing Sustainability Risks', 'The FMA Guide for Managing Sustainability Risks in Austria, 2025, outlines international sustainability regulations and their impact on the economy and financial markets. It provides definitions, legal frameworks, and risk management strategies for climate, environmental, social, and governance risks, targeting financial institutions and regulators.', 'The FMA Guide for Managing Sustainability Risks in Austria, 2025, outlines international sustainability regulations and their impact on the economy and financial markets. It provides definitions, legal frameworks, and risk management strategies for climate, environmental, social, and governance risks, targeting financial institutions and regulators.', 'The FMA Guide for Managing Sustainability Risks in Austria, 2025, outlines international sustainability regulations and their impact on the economy and financial markets. It provides definitions, legal frameworks, and risk management strategies for climate, environmental, social, and governance risks, targeting financial institutions and regulators.', 'Austria', 'climate', 'in_force', '2025-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_29', ARRAY['sdg13', 'regulations', 'mandatory', 'austria', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06e09804-3dfc-5097-9eee-383e0c23b4f0', 'Austria Consolidated federal law: Complete legal text for the', 'Consolidated federal law: Complete legal text for the Corporate Liability Act, version of 13.12.2025', 'Austria''s Corporate Liability Act outlines the responsibility of organizations for criminal offenses, defining entities covered and sanctions. Decision-makers and employees are specified, along with penalties like corporate fines based on the severity of the offense. Targeted at legal entities and individuals in leadership roles within organizations.', 'Austria''s Corporate Liability Act outlines the responsibility of organizations for criminal offenses, defining entities covered and sanctions. Decision-makers and employees are specified, along with penalties like corporate fines based on the severity of the offense. Targeted at legal entities and individuals in leadership roles within organizations.', 'Austria''s Corporate Liability Act outlines the responsibility of organizations for criminal offenses, defining entities covered and sanctions. Decision-makers and employees are specified, along with penalties like corporate fines based on the severity of the offense. Targeted at legal entities and individuals in leadership roles within organizations.', 'Austria', 'governance', 'in_force', '2025-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_33', ARRAY['mandatory', 'austria', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('363830e6-ebda-51cc-8add-d062f6a8de10', 'Austria Sustainability Reporting Act', 'Sustainability Reporting Act', 'The Sustainability Reporting Act mandates certain foreign companies operating in Austria to submit sustainability reports. This law applies to large capital companies and registered partnerships whose parent companies do not fall under EU jurisdiction but meet specific revenue thresholds. The reports must detail the company''s business model, sustainability strategies, and stakeholder impacts, aligning with EU climate goals. It aims to enhance transparency and accountability regarding sustainability practices. The reporting is mandatory for qualifying entities.', 'The Sustainability Reporting Act mandates certain foreign companies operating in Austria to submit sustainability reports. This law applies to large capital companies and registered partnerships whose parent companies do not fall under EU jurisdiction but meet specific revenue thresholds. The reports must detail the company''s business model, sustainability strategies, and stakeholder impacts, aligning with EU climate goals. It aims to enhance transparency and accountability regarding sustainability practices. The reporting is mandatory for qualifying entities.', 'The Sustainability Reporting Act mandates certain foreign companies operating in Austria to submit sustainability reports. This law applies to large capital companies and registered partnerships whose parent companies do not fall under EU jurisdiction but meet specific revenue thresholds. The reports must detail the company''s business model, sustainability strategies, and stakeholder impacts, aligning with EU climate goals. It aims to enhance transparency and accountability regarding sustainability practices. The reporting is mandatory for qualifying entities.', 'Austria', 'climate', 'in_force', '2025-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_34', ARRAY['sdg13', 'regulations', 'sdg17', 'mandatory', 'austria', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('95aa52b0-9b8e-5c2a-8ebe-da3283420b0a', 'Austria Federal Act on Special Civil Law Provisions', 'Federal Act on Special Civil Law Provisions for Companies (Company Code –UGB)', 'The Federal Act on Special Civil Law Provisions for Companies in Austria, known as the Company Code (UGB), outlines legal regulations for businesses. It specifies civil law provisions, amendments, and legislative history, primarily targeting companies operating in Austria.', 'The Federal Act on Special Civil Law Provisions for Companies in Austria, known as the Company Code (UGB), outlines legal regulations for businesses. It specifies civil law provisions, amendments, and legislative history, primarily targeting companies operating in Austria.', 'The Federal Act on Special Civil Law Provisions for Companies in Austria, known as the Company Code (UGB), outlines legal regulations for businesses. It specifies civil law provisions, amendments, and legislative history, primarily targeting companies operating in Austria.', 'Austria', 'governance', 'in_force', '2023-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_31', ARRAY['mandatory', 'austria', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7b4146e5-1b81-5f13-9a95-c57d556a1059', 'Austria Sustainability reporting Guidance for issuers', 'Sustainability reporting Guidance for issuers', 'The 2023 Sustainability Reporting Guidance for Issuers by the Vienna Stock Exchange aids listed and non-listed companies in understanding and meeting sustainability reporting standards. It aligns with global initiatives, highlights statutory requirements, and targets stakeholders like investors and analysts, promoting transparency and ESG integration.', 'The 2023 Sustainability Reporting Guidance for Issuers by the Vienna Stock Exchange aids listed and non-listed companies in understanding and meeting sustainability reporting standards. It aligns with global initiatives, highlights statutory requirements, and targets stakeholders like investors and analysts, promoting transparency and ESG integration.', 'The 2023 Sustainability Reporting Guidance for Issuers by the Vienna Stock Exchange aids listed and non-listed companies in understanding and meeting sustainability reporting standards. It aligns with global initiatives, highlights statutory requirements, and targets stakeholders like investors and analysts, promoting transparency and ESG integration.', 'Austria', 'climate', 'in_force', '2023-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_32', ARRAY['sdg16', 'guidance_frameworks', 'mandatory', 'austria']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf39b926-d464-5a4a-b03e-aacb336d92f9', 'Austrian Corporate Governance Code (Österreichischer Corporate Governance Kodex)', 'Austrian Corporate Governance Code (Österreichischer Corporate Governance Kodex)', 'The plan lays out key measures in sectors such as transport, buildings, energy production, and agriculture to promote sustainability. Notable projects include e-mobility, energy-efficient buildings, and increased use of biomass and solar power. The plan also discusses the need for improving public transport infrastructure, enhancing energy efficiency in industries, and expanding green energy sources through government incentives.', 'The plan lays out key measures in sectors such as transport, buildings, energy production, and agriculture to promote sustainability. Notable projects include e-mobility, energy-efficient buildings, and increased use of biomass and solar power. The plan also discusses the need for improving public transport infrastructure, enhancing energy efficiency in industries, and expanding green energy sources through government incentives.', 'The plan lays out key measures in sectors such as transport, buildings, energy production, and agriculture to promote sustainability. Notable projects include e-mobility, energy-efficient buildings, and increased use of biomass and solar power. The plan also discusses the need for improving public transport infrastructure, enhancing energy efficiency in industries, and expanding green energy sources through government incentives.', 'Austria', 'climate', 'in_force', '2023-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_8', ARRAY['sdg2', 'sdg7', 'sdg11', 'mandatory', 'austria', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('05b47a0b-b44e-51f4-bc29-0c1da0ea2e25', 'Austria Stock Exchange Regulations on ESG Disclosures (Vienna Stock', 'Stock Exchange Regulations on ESG Disclosures (Vienna Stock Exchange)', 'The Vienna ESG Segment is a dedicated segment of the Wiener Börse AG (Vienna Stock Exchange) designed for trading bonds issued by entities that adhere to stringent Environmental, Social, and Governance (ESG) standards. This segment facilitates the listing of sustainable bonds, including green bonds, social bonds, sustainability-linked bonds, and transition bonds. It aims to ensure that participating issuers meet high standards of transparency, disclosure, and ESG impact through regular reporting, external reviews, and compliance with recognized standards, such as the ICMA Green Bond Principles and the EU Green Bond Standard.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5dd76b0a-0f52-55ff-9f05-8b7da4f7e267', 'Austrian Sustainability and Climate Strategy (Klimaschutzgesetz)', 'Austrian Sustainability and Climate Strategy (Klimaschutzgesetz)', 'The Austrian Strategy for Adaptation to Climate Change outlines Austria''s approach to addressing the impacts of climate change across multiple sectors, such as agriculture, forestry, water management, tourism, and energy. The strategy is based on a dual approach: mitigation and adaptation. The strategy emphasizes the importance of cross-sectoral cooperation and the integration of climate adaptation measures into planning and decision-making. Key objectives include building resilience in the face of climate impacts, safeguarding ecosystem services, ensuring water availability, protecting biodiversity, and strengthening the economic sectors to thrive in changing climatic conditions. The strategy also highlights the need for public awareness and research to support climate-resilient practices.', 'The Austrian Strategy for Adaptation to Climate Change outlines Austria''s approach to addressing the impacts of climate change across multiple sectors, such as agriculture, forestry, water management, tourism, and energy. The strategy is based on a dual approach: mitigation and adaptation. The strategy emphasizes the importance of cross-sectoral cooperation and the integration of climate adaptation measures into planning and decision-making. Key objectives include building resilience in the face of climate impacts, safeguarding ecosystem services, ensuring water availability, protecting biodiversity, and strengthening the economic sectors to thrive in changing climatic conditions. The strategy also highlights the need for public awareness and research to support climate-resilient practices.', 'The Austrian Strategy for Adaptation to Climate Change outlines Austria''s approach to addressing the impacts of climate change across multiple sectors, such as agriculture, forestry, water management, tourism, and energy. The strategy is based on a dual approach: mitigation and adaptation. The strategy emphasizes the importance of cross-sectoral cooperation and the integration of climate adaptation measures into planning and decision-making. Key objectives include building resilience in the face of climate impacts, safeguarding ecosystem services, ensuring water availability, protecting biodiversity, and strengthening the economic sectors to thrive in changing climatic conditions. The strategy also highlights the need for public awareness and research to support climate-resilient practices.', 'Austria', 'climate', 'in_force', '2021-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_1', ARRAY['sdg2', 'sdg13', 'sdg14', 'sdg7', 'mandatory', 'sdg6', 'austria', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a47cf05f-8d8b-51be-8c19-d274886df6e6', 'Austria Sustainable Finance Act (Sustainable Finance Gesetz)', 'Sustainable Finance Act (Sustainable Finance Gesetz)', 'The Austrian Green Finance Agenda aims to channel private financial flows into low-emission and sustainable investments, as well as better manage sustainability risks, in line with Austria''s climate goals. The strategy sets out specific measures to create a climate-friendly financial sector, increase the flow of green investments, and align financial market activities with Austria''s climate targets. It includes actions such as issuing government green bonds, expanding the range of green financial instruments, and bolstering green project financing.', 'The Austrian Green Finance Agenda aims to channel private financial flows into low-emission and sustainable investments, as well as better manage sustainability risks, in line with Austria''s climate goals. The strategy sets out specific measures to create a climate-friendly financial sector, increase the flow of green investments, and align financial market activities with Austria''s climate targets. It includes actions such as issuing government green bonds, expanding the range of green financial instruments, and bolstering green project financing.', 'The Austrian Green Finance Agenda aims to channel private financial flows into low-emission and sustainable investments, as well as better manage sustainability risks, in line with Austria''s climate goals. The strategy sets out specific measures to create a climate-friendly financial sector, increase the flow of green investments, and align financial market activities with Austria''s climate targets. It includes actions such as issuing government green bonds, expanding the range of green financial instruments, and bolstering green project financing.', 'Austria', 'climate', 'in_force', '2021-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_2', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'austria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5c6dc61d-6cba-5152-9c8d-ed7f01f8bca6', 'Austrian Code of Corporate Governance January', 'Austrian Code of Corporate Governance January 2021', 'The Austrian Code of Corporate Governance version of January 2021 adapts the provisions of the L-Rules to the amendments to the law.', 'The Austrian Code of Corporate Governance version of January 2021 adapts the provisions of the L-Rules to the amendments to the law.', 'The Austrian Code of Corporate Governance version of January 2021 adapts the provisions of the L-Rules to the amendments to the law.', 'Austria', 'climate', 'in_force', '2021-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_26', ARRAY['regulations', 'sdg7', 'mandatory', 'austria', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('524dee95-b0bb-53dd-becb-713a149f6329', 'Austria FMA Guide for Managing Sustainability', 'FMA Guide for Managing Sustainability 2020', 'This guide is intended to provide supervised entities with know-how, while also promoting the development of a common understanding.', 'This guide is intended to provide supervised entities with know-how, while also promoting the development of a common understanding.', 'This guide is intended to provide supervised entities with know-how, while also promoting the development of a common understanding.', 'Austria', 'climate', 'in_force', '2020-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_12', ARRAY['sdg7', 'mandatory', 'austria', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6f87adf6-1563-5f85-b61b-a4e789f81f5a', 'Out of responsibility for Austria', 'Out of responsibility for Austria', 'This document outlines the Austrian programme that aims to take responsibility towards the people in Austria and towards parliamentarism and good cooperation as well as towards the value of compromise and exchange for democracy.', 'This document outlines the Austrian programme that aims to take responsibility towards the people in Austria and towards parliamentarism and good cooperation as well as towards the value of compromise and exchange for democracy.', 'This document outlines the Austrian programme that aims to take responsibility towards the people in Austria and towards parliamentarism and good cooperation as well as towards the value of compromise and exchange for democracy.', 'Austria', 'climate', 'in_force', '2020-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_25', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg17', 'mandatory', 'austria', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('787c77f0-b09d-5a90-9dca-354ebb4effee', 'Austrian Code of Corporate Governance January', 'Austrian Code of Corporate Governance January 2020', 'The "Österreichischer Corporate Governance Kodex" is a code of best practices for corporate governance in Austria, which was last updated in January 2020. The code aims to promote transparency, accountability, and responsible management in Austrian companies, with a particular focus on listed companies. The code includes principles and recommendations related to the composition and functioning of the board of directors, the role and responsibilities of the CEO, shareholder rights and engagement, risk management, and corporate social responsibility. The code is voluntary, but listed companies are required to disclose whether they comply with its recommendations and to explain any deviations.', 'The "Österreichischer Corporate Governance Kodex" is a code of best practices for corporate governance in Austria, which was last updated in January 2020. The code aims to promote transparency, accountability, and responsible management in Austrian companies, with a particular focus on listed companies. The code includes principles and recommendations related to the composition and functioning of the board of directors, the role and responsibilities of the CEO, shareholder rights and engagement, risk management, and corporate social responsibility. The code is voluntary, but listed companies are required to disclose whether they comply with its recommendations and to explain any deviations.', 'The "Österreichischer Corporate Governance Kodex" is a code of best practices for corporate governance in Austria, which was last updated in January 2020. The code aims to promote transparency, accountability, and responsible management in Austrian companies, with a particular focus on listed companies. The code includes principles and recommendations related to the composition and functioning of the board of directors, the role and responsibilities of the CEO, shareholder rights and engagement, risk management, and corporate social responsibility. The code is voluntary, but listed companies are required to disclose whether they comply with its recommendations and to explain any deviations.', 'Austria', 'governance', 'in_force', '2020-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_28', ARRAY['regulations', 'mandatory', 'austria', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('69f6ea7a-4b13-5c4a-9c27-c6c330c93669', 'Austria EU Taxonomy for Sustainable Activities', 'EU Taxonomy for Sustainable Activities', 'The changes also seek to address investor needs for comparable, reliable, and relevant sustainability data, ensuring that companies disclose information on the impact of their activities on society and the environment. It integrates double materiality into the reporting process, emphasizing the need to disclose both the risks sustainability issues pose to businesses and the impacts of business activities on society and the environment.', 'The changes also seek to address investor needs for comparable, reliable, and relevant sustainability data, ensuring that companies disclose information on the impact of their activities on society and the environment. It integrates double materiality into the reporting process, emphasizing the need to disclose both the risks sustainability issues pose to businesses and the impacts of business activities on society and the environment.', 'The changes also seek to address investor needs for comparable, reliable, and relevant sustainability data, ensuring that companies disclose information on the impact of their activities on society and the environment. It integrates double materiality into the reporting process, emphasizing the need to disclose both the risks sustainability issues pose to businesses and the impacts of business activities on society and the environment.', 'Austria', 'climate', 'in_force', '2020-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_4', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'austria', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
